package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Test

private class FakeClock(var time: Long = 0L) : Clock {
    override fun now(): Long = time
}

class CacheTtlTest {

    @Test
    fun entriesWithoutTtlNeverExpire() {
        val clock = FakeClock(0)
        val cache = Cache<String, Int>(clock)
        cache.put("a", 1)
        clock.time = 1_000_000L
        assertEquals(1, cache.get("a"))
    }

    @Test
    fun entryExpiresAtItsExpiryInstantInclusive() {
        val clock = FakeClock(0)
        val cache = Cache<String, Int>(clock)
        cache.put("a", 1, ttlMillis = 100)

        clock.time = 99
        assertEquals(1, cache.get("a"), "just before expiry: still present")

        clock.time = 100
        assertNull(cache.get("a"), "AT the expiry instant: must already be expired")
    }

    @Test
    fun expiredEntryIsActuallyRemovedNotJustHidden() {
        val clock = FakeClock(0)
        val cache = Cache<String, Int>(clock)
        cache.put("a", 1, ttlMillis = 50)
        clock.time = 50
        cache.get("a")
        assertEquals(0, cache.size(), "expired entries must be evicted from the store, not just skipped on read")
    }

    @Test
    fun independentKeysHaveIndependentTtls() {
        val clock = FakeClock(0)
        val cache = Cache<String, Int>(clock)
        cache.put("short", 1, ttlMillis = 10)
        cache.put("long", 2, ttlMillis = 1000)
        clock.time = 10
        assertNull(cache.get("short"))
        assertEquals(2, cache.get("long"))
    }
}

