package com.optarena.app

fun interface Clock {
    fun now(): Long
}

class Cache<K, V>(private val clock: Clock = Clock { System.currentTimeMillis() }) {
    private data class Entry<V>(val value: V, val expiresAt: Long?)

    private val store = HashMap<K, Entry<V>>()

    /** ttlMillis null (or omitted) means the entry never expires. */
    fun put(key: K, value: V, ttlMillis: Long? = null) {
        val expiresAt = ttlMillis?.let { clock.now() + it }
        store[key] = Entry(value, expiresAt)
    }

    /** An entry is considered expired AT its expiry instant, not just after it. */
    fun get(key: K): V? {
        val entry = store[key] ?: return null
        if (entry.expiresAt != null && clock.now() >= entry.expiresAt) {
            store.remove(key)
            return null
        }
        return entry.value
    }

    fun size(): Int = store.size
}

